import type pg from "pg";
import { FencingTokenMismatchError } from "./errors.js";
import { withWebTransaction } from "./web-authorization.js";

/** Publish domain state and the task result atomically, fenced against cancellation/expiry. */
export async function publishTaskResult(pool: pg.Pool, taskId: string, workerId: string, fenceToken: bigint,
  result: Record<string,unknown> | null, publish: (db:pg.PoolClient)=>Promise<void>, park = false,
):Promise<void> {
  await withWebTransaction(pool,async db=>{
    const owned=await db.query(`SELECT id FROM task_executions WHERE id=$1 AND status='running'
      AND lease_owner=$2 AND fence_token=$3 AND lease_expires_at>clock_timestamp() AND cancel_requested_at IS NULL FOR UPDATE`,[taskId,workerId,fenceToken.toString()]);
    if(!owned.rowCount) throw new FencingTokenMismatchError('Publication rejected: expired lease, cancellation or ownership changed');
    await publish(db);
    const done=await db.query(`UPDATE task_executions SET status=$5,result_ref=$4::jsonb,
      lease_owner=NULL,lease_expires_at=NULL,updated_at=clock_timestamp()
      WHERE id=$1 AND lease_owner=$2 AND fence_token=$3 AND status='running'
        AND lease_expires_at>clock_timestamp() AND cancel_requested_at IS NULL`,[taskId,workerId,fenceToken.toString(),JSON.stringify(result),park?"awaiting_confirmation":"succeeded"]);
    if(!done.rowCount) throw new FencingTokenMismatchError('Lease expired during publication');
  });
}

import type pg from "pg";

export class WebAccessError extends Error {
  constructor(readonly statusCode: number, readonly code: string, message: string) { super(message); }
}
export interface AuthorizedBaby { family_id: string; baby_id: string; timezone: string; nickname: string; birth_date: Date; role: string; family_role: string }
export type Queryable = Pick<pg.Pool, "query">;

/** Recheck the current database membership, including family ownership and deletion. */
export async function requireWebBaby(db: Queryable, userId: string, babyId: string, lock = false, requireWrite = false): Promise<AuthorizedBaby> {
  const result = await db.query<AuthorizedBaby>(`SELECT b.family_id, b.id AS baby_id, f.timezone, b.nickname, b.birth_date, bm.role, fm.role AS family_role
    FROM babies b JOIN families f ON f.id = b.family_id
    JOIN baby_members bm ON bm.baby_id = b.id AND bm.family_id = b.family_id AND bm.user_id = $1
    JOIN family_members fm ON fm.family_id = b.family_id AND fm.user_id = bm.user_id
    WHERE b.id = $2 AND b.deleted_at IS NULL AND f.deleted_at IS NULL
      AND bm.status = 'active' AND bm.deleted_at IS NULL
      AND fm.status = 'active' AND fm.deleted_at IS NULL
    ${lock ? "FOR SHARE OF b, f, bm, fm" : ""}`, [userId, babyId]);
  const baby = result.rows[0];
  if (!baby) throw new WebAccessError(404, "BABY_NOT_FOUND", "Baby not found or no longer authorized");
  if(requireWrite && (baby.role === "viewer" || baby.family_role === "viewer")) throw new WebAccessError(403,"BABY_WRITE_DENIED","Read-only members cannot publish shared baby summaries");
  return baby;
}
export async function withWebTransaction<T>(pool: pg.Pool, work: (db: pg.PoolClient) => Promise<T>): Promise<T> {
  const db = await pool.connect();
  try {
    await db.query("BEGIN");
    const result = await work(db);
    await db.query("COMMIT");
    return result;
  } catch (error) {
    try { await db.query("ROLLBACK"); } catch { /* Preserve the original failure. */ }
    throw error;
  } finally { db.release(); }
}
